import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"6、【訟】 坎下乾上","description":"子夏易傳 - 6、【訟】 坎下乾上","frontmatter":{"title":"6、【訟】 坎下乾上","description":"子夏易傳 - 6、【訟】 坎下乾上"},"headers":[],"relativePath":"classics/zixia/008.md","filePath":"classics/zixia/008.md"}'),i={name:"classics/zixia/008.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_6、【訟】-坎下乾上" tabindex="-1">6、【訟】 坎下乾上 <a class="header-anchor" href="#_6、【訟】-坎下乾上" aria-label="Permalink to “6、【訟】 坎下乾上”">​</a></h1><p>卦辭：訟，有孚，窒惕，中吉，終兇。</p><p>利見大人，不利涉大川。彖曰：訟上剛下險，險而健訟，訟有孚，窒惕，中吉。剛來而得中也，終兇。訟不可成也。利見大人，尚中正也。不利涉大川，入於淵也。</p><p>子夏：君子知微、知彰、知柔、知剛，能盡物之情也。訟之者，其昧於先乎，兩其情，則上剛而下險，兼其象，則中心險而行健，得無訟乎。訟之所由興於二也，內剛險也。居中理可信也，不中塞也，上健可懼也。直可申也，故中吉。人不與訟也，故終兇。大人志尚中正者，利而見之辨也。陷於下矣，又好爭焉，故可涉於險也。</p><p>象曰：天與水違，行訟君子，以作事謀始。</p><p>子夏：相違而與處事，訟之象也。君子見其未著，防其未形，則逺訟也。</p><p>初六，不永所事，小有言，終吉。</p><p>象曰：不永所事，訟不可長也。雖小有言，其辨明也。</p><p>子夏：柔非勇於訟也，上迫而至訟。訟初有言，辨明而通，其志不長，其訟得於終吉之道也。訟之長，兇之咎也。其吉於初已乎。</p><p>九二，不克訟，歸而逋，其邑人三百戶，無眚。</p><p>象曰：不克訟，歸逋，竄也。自下訟上，患至掇也。</p><p>子夏：為下訟上，訟可得乎，自貽其患也。不可而退，還竄其邑，自守其寡，不敢上敵，猶無眚也。</p><p>六三，食舊德，貞厲，終吉。或從王事，無成。</p><p>象曰：食舊德，從上吉也。</p><p>子夏：處下之上，從乎剛陽，而訟通矣，食其德矣。乘剛而待之，危也。從上得附，故終吉矣。夫以柔附上，非聽其訟亦，為上忤矣。故至有命，則行之不敢自成也。夫不爭於外者，善矣夫。</p><p>九四，不克訟，復即命渝，安貞吉。</p><p>象曰：復即命，渝安貞，不失也。</p><p>子夏：三柔附我，故我不能敵，初之訟也。以就三之命，變其訟之應也。安貞而吉，何所失哉。</p><p>九五，訟元吉。</p><p>象曰：訟元吉，以中正也。</p><p>子夏：中正上行，雖訟而吉大也。</p><p>上九，或錫之鞶帶，終朝三褫之。</p><p>象曰：以訟受服，亦不足敬也。</p><p>子夏：剛居訟，終能訟而得其終也。專攻得其非，上或賞也。三脫其服，象褫疾也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
